void TestDeflateFixtures() {
	const auto raw = ReadBytes("deflate/chunk.raw");
	const auto zlib = ReadBytes("deflate/chunk.zlib");
	const auto gzip = ReadBytes("deflate/chunk.gzip");
	const auto rawDeflate = ReadBytes("deflate/chunk.raw-deflate");

	auto zlibOut = Deflate::Decompress(Deflate::Format::Zlib, zlib, raw.size());
	CHECK(zlibOut.has_value());
	CHECK(zlibOut && *zlibOut == raw);

	auto gzipOut = Deflate::Decompress(Deflate::Format::Gzip, gzip);
	CHECK(gzipOut.has_value());
	CHECK(gzipOut && *gzipOut == raw);

	auto rawOut = Deflate::Decompress(Deflate::Format::Raw, rawDeflate);
	CHECK(rawOut.has_value());
	CHECK(rawOut && *rawOut == raw);

	CHECK(Deflate::Decompress(Deflate::Format::Zlib, ReadBytes("deflate/empty.zlib")).value_or(std::vector<uint8_t>{ 1 }).empty());
	CHECK_EQ(Deflate::Decompress(Deflate::Format::Zlib, ReadBytes("deflate/one-byte.zlib")).value_or(std::vector<uint8_t>{}),
	         std::vector<uint8_t>{ 'x' });

	CHECK(!Deflate::Decompress(Deflate::Format::Zlib, ReadBytes("deflate/chunk.corrupt.zlib")).has_value());

	std::vector<uint8_t> out(raw.size());
	size_t written = 0;
	CHECK(Deflate::Decompress(Deflate::Format::Zlib, zlib, out, written));
	CHECK_EQ(written, raw.size());
	CHECK(out == raw);

	std::vector<uint8_t> tooSmall(raw.size() - 1);
	CHECK(!Deflate::Decompress(Deflate::Format::Zlib, zlib, tooSmall, written));

	for (auto format : { Deflate::Format::Raw, Deflate::Format::Zlib, Deflate::Format::Gzip }) {
		auto compressed = Deflate::Compress(format, raw, 1);
		CHECK(!compressed.empty());
		auto roundTrip = Deflate::Decompress(format, compressed, raw.size());
		CHECK(roundTrip.has_value());
		CHECK(roundTrip && *roundTrip == raw);
	}

	CHECK(Deflate::CompressBound(Deflate::Format::Zlib, raw.size(), 1) > raw.size());
	CHECK(Deflate::CompressBound(Deflate::Format::Zlib, raw.size(), 100) > raw.size());
}

void TestNbtKitchenSink() {
	const auto fixture = ReadBytes("nbt/kitchen_sink.nbt");
	Tag root = ParseNbt(fixture);
	CHECK_EQ(root.type, TAG_COMPOUND);
	CHECK_EQ(root.name, std::string("Root"));
	CHECK_EQ(root.Get("title").GetString(), std::string("BPP fixture: kitchen sink"));
	CHECK_EQ(root.Get("version").GetInt(), 1);

	const Tag& nested = root.Get("nested");
	CHECK_EQ(nested.Get("byte").GetByte(), int8_t(-128));
	CHECK_EQ(nested.Get("short").GetShort(), int16_t(-32768));
	CHECK_EQ(nested.Get("int").GetInt(), std::numeric_limits<int32_t>::min());
	CHECK_EQ(nested.Get("long").GetLong(), std::numeric_limits<int64_t>::min());
	CHECK_EQ(nested.Get("float").GetFloat(), 3.1415927f);
	CHECK_EQ(nested.Get("double").GetDouble(), -2.718281828459045);
	CHECK_EQ(nested.Get("string").GetString(), std::string("héllo ☃ 世界"));

	const auto& bytes = nested.Get("bytes").GetByteArray();
	CHECK_EQ(bytes.size(), size_t(256));
	for (size_t i = 0; i < bytes.size(); ++i)
		CHECK_EQ(bytes[i], int8_t(i));

	const auto& ints = nested.Get("ints").GetIntArray();
	CHECK_EQ(ints, std::vector<int32_t>({ std::numeric_limits<int32_t>::min(), -1, 0, 1,
	                                      std::numeric_limits<int32_t>::max() }));
	CHECK(nested.Get("emptyCompound").GetCompound().empty());
	CHECK(nested.Get("emptyList").GetList().empty());
	CHECK_EQ(nested.Get("strings").GetList().size(), size_t(3));
	CHECK_EQ(nested.Get("strings").GetList()[1].GetString(), std::string("βeta"));
	CHECK_EQ(nested.Get("compounds").GetList().size(), size_t(2));
	CHECK_EQ(nested.Get("compounds").GetList()[1].Get("name").GetString(), std::string("second"));

	auto written = WriteNbt(root);
	Tag reparsed = ParseNbt(written);
	CHECK(TagEqual(root, reparsed));
	CHECK_EQ(written.size(), fixture.size());
}

void TestNbtChunkLike() {
	const auto fixture = ReadBytes("nbt/chunk_like.nbt");
	Tag root = ParseNbt(fixture);
	const Tag& level = root.Get("Level");
	CHECK_EQ(level.Get("xPos").GetInt(), 12);
	CHECK_EQ(level.Get("zPos").GetInt(), -34);
	CHECK_EQ(level.Get("LastUpdate").GetLong(), int64_t(9876543210));
	CHECK_EQ(level.Get("Blocks").GetByteArray().size(), size_t(180 * 1024));
	CHECK_EQ(level.Get("Data").GetByteArray().size(), size_t(90 * 1024));

	auto written = WriteNbt(root);
	Tag reparsed = ParseNbt(written);
	CHECK(TagEqual(root, reparsed));
	CHECK_EQ(written.size(), fixture.size());
}

void TestNbtMalformed() {
	auto truncated = ReadBytes("nbt/truncated.nbt");
	bool threw = false;
	try {
		ParseNbt(truncated);
	} catch (const std::exception&) {
		threw = true;
	}
	CHECK(threw);

	std::vector<uint8_t> badRoot { TAG_INT, 0, 0, 0x7F, 0xFF, 0xFF, 0xFF };
	threw = false;
	try {
		ParseNbt(badRoot);
	} catch (const std::exception&) {
		threw = true;
	}
	CHECK(threw);

	auto badList = ReadBytes("nbt/bad_list.nbt");
	threw = false;
	try {
		ParseNbt(badList);
	} catch (const std::exception&) {
		threw = true;
	}
	CHECK(threw);
}

void TestUcs2Fixtures() {
	const std::string utf8 = ReadText("ucs2/text.utf8");
	const auto utf16le = ReadBytes("ucs2/text.utf16le");
	CHECK_EQ(utf16le.size() % 2, size_t(0));

	std::u16string expected;
	expected.reserve(utf16le.size() / 2);
	for (size_t i = 0; i < utf16le.size(); i += 2)
		expected.push_back(static_cast<char16_t>(uint16_t(utf16le[i]) | (uint16_t(utf16le[i + 1]) << 8)));

	CHECK_EQ(ToUCS2(utf8), expected);
	CHECK_EQ(ToUTF8(expected), utf8);

	CHECK_EQ(ToUCS2("plain ascii"), std::u16string(u"plain ascii"));
	CHECK_EQ(ToUTF8(u"plain ascii"), std::string("plain ascii"));
	CHECK(ToUCS2("\xF0\x9F\x98\x80").empty()); // UTF-16 surrogate pair, not representable in UCS-2
	CHECK_EQ(StripFormatting("\xA7" "cRed\xA7" "r text"), std::string("Red text"));

	size_t index = 0;
	CHECK_EQ(DecodeUTF8Char("A", index), char32_t('A'));
	CHECK_EQ(index, size_t(1));
	index = 0;
	CHECK_EQ(DecodeUTF8Char("é", index), char32_t(0xE9));
	CHECK_EQ(index, size_t(2));
}

void BuildSyntheticChunk(Chunk& _chunk) {
	for (int x = 0; x < CHUNK_WIDTH; ++x) {
		for (int z = 0; z < CHUNK_WIDTH; ++z) {
			for (int y = 0; y < CHUNK_HEIGHT; ++y) {
				const int li = SubChunk::LocalIndex({ x, y, z });
				SubChunk& sub = _chunk.subChunks[size_t(y >> 4)];
				sub.SetBlock(li, BlockType((x * 7 + y * 3 + z * 5) % 16));
				sub.SetMeta(li, uint8_t((x * 5 + y * 7 + z * 11) % 16));
				sub.SetBlockLight(li, uint8_t((x * 13 + y * 17 + z * 19) % 16));
				sub.SetSkyLight(li, uint8_t((x * 23 + y * 29 + z * 31) % 16));
			}
		}
	}
	_chunk.cpos = { 0, 0 };
}

void TestChunkSerializerFixture() {
	Chunk chunk;
	BuildSyntheticChunk(chunk);

	const auto expected = ReadBytes("chunk/synthetic.raw");
	auto compressed = ChunkSerializer::Serialize(chunk);
	auto decompressed = Deflate::Decompress(Deflate::Format::Zlib, compressed, expected.size());
	CHECK(decompressed.has_value());
	CHECK(decompressed && *decompressed == expected);

	const auto expectedSub = ReadBytes("chunk/subregion.raw");
	auto compressedSub = ChunkSerializer::Serialize(chunk, 3, 10, 17, 23, 5, 12);
	auto decompressedSub = Deflate::Decompress(Deflate::Format::Zlib, compressedSub, expectedSub.size());
	CHECK(decompressedSub.has_value());
	CHECK(decompressedSub && *decompressedSub == expectedSub);
}

void TestRegionFixture() {
	TempDir temp("region");
	const auto target = temp.path / "r.0.0.mcr";
	std::filesystem::copy_file(Fixture("region/r.0.0.mcr"), target);

	Region region(Int32_2{ 0, 0 }, temp.path.string());
	Region::ReadStatus status = Region::ReadStatus::Error;
	auto chunk = region.GetChunk(Int32_2{ 0, 0 }, status);
	CHECK_EQ(status, Region::ReadStatus::Ok);
	CHECK(chunk != nullptr);
	if (!chunk)
		return;

	CHECK_EQ(chunk->cpos.x, 0);
	CHECK_EQ(chunk->cpos.z, 0);
	for (int x = 0; x < CHUNK_WIDTH; ++x) {
		for (int z = 0; z < CHUNK_WIDTH; ++z) {
			CHECK_EQ(chunk->heightMap[z * CHUNK_WIDTH + x], uint8_t((x * 3 + z * 7) % CHUNK_HEIGHT));
			for (int y = 0; y < CHUNK_HEIGHT; ++y) {
				const int block = (x * 7 + y * 3 + z * 5) % 16;
				const int meta = (x * 5 + y * 7 + z * 11) % 16;
				const int blockLight = (x * 13 + y * 17 + z * 19) % 16;
				const int skyLight = (x * 23 + y * 29 + z * 31) % 16;
				CHECK_EQ(int(chunk->GetBlock({ x, y, z })), block);
				CHECK_EQ(int(chunk->GetMeta({ x, y, z })), meta);
				CHECK_EQ(int(chunk->GetBlockLight({ x, y, z })), blockLight);
				CHECK_EQ(int(chunk->GetSkyLight({ x, y, z })), skyLight);
			}
		}
	}

	auto encoded = region.EncodeNbtData(chunk, 424242, nullptr);
	CHECK(!encoded.empty());
	auto decoded = region.DecodeNbtData(encoded);
	CHECK(decoded != nullptr);
	if (!decoded)
		return;
	CHECK_EQ(decoded->cpos, chunk->cpos);
	CHECK_EQ(decoded->isTerrainPopulated, chunk->isTerrainPopulated);
	CHECK(std::equal(std::begin(decoded->heightMap), std::end(decoded->heightMap), std::begin(chunk->heightMap)));
	for (int x = 0; x < CHUNK_WIDTH; ++x) {
		for (int z = 0; z < CHUNK_WIDTH; ++z) {
			for (int y = 0; y < CHUNK_HEIGHT; ++y) {
				CHECK_EQ(int(decoded->GetBlock({ x, y, z })), int(chunk->GetBlock({ x, y, z })));
				CHECK_EQ(int(decoded->GetMeta({ x, y, z })), int(chunk->GetMeta({ x, y, z })));
				CHECK_EQ(int(decoded->GetBlockLight({ x, y, z })), int(chunk->GetBlockLight({ x, y, z })));
				CHECK_EQ(int(decoded->GetSkyLight({ x, y, z })), int(chunk->GetSkyLight({ x, y, z })));
			}
		}
	}
}

void TestRegionOverwriteReusesSectors() {
	TempDir temp("region-overwrite");
	const auto target = temp.path / "r.0.0.mcr";
	{
		std::ofstream file(target, std::ios::binary);
		std::string zeros(8192, '\0');
		file.write(zeros.data(), static_cast<std::streamsize>(zeros.size()));
	}

	Region region(Int32_2{ 0, 0 }, temp.path.string());
	auto chunk = std::make_shared<Chunk>();
	BuildSyntheticChunk(*chunk);
	CHECK(region.AddChunk(chunk, 1, nullptr));
	const auto firstSize = std::filesystem::file_size(target);
	CHECK(region.AddChunk(chunk, 2, nullptr));
	const auto secondSize = std::filesystem::file_size(target);
	CHECK_EQ(firstSize, secondSize);

	Region::ReadStatus status = Region::ReadStatus::Error;
	auto loaded = region.GetChunk(Int32_2{ 0, 0 }, status);
	CHECK_EQ(status, Region::ReadStatus::Ok);
	CHECK(loaded != nullptr);
	if (loaded)
		CHECK_EQ(int(loaded->GetBlock({ 7, 42, 9 })), int(chunk->GetBlock({ 7, 42, 9 })));
}

void TestRegionManagerSaveQueue() {
	TempDir temp("region-manager");
	RegionManager manager;
	CHECK(manager.Initialize(temp.path.string()));

	auto chunk = std::make_shared<Chunk>();
	BuildSyntheticChunk(*chunk);

	// Saving the same chunk twice before a flush must only keep the newest
	// snapshot, not queue two copies.
	manager.SaveChunk(chunk, false);
	manager.SaveChunk(chunk, false);
	manager.FlushAll();

	manager.LoadChunk(Int32_2{ 0, 0 });
	manager.iopool.wait();
	auto loaded = manager.GetChunk(Int32_2{ 0, 0 });
	CHECK(loaded != nullptr);
	if (loaded)
		CHECK_EQ(int(loaded->GetBlock({ 3, 60, 4 })), int(chunk->GetBlock({ 3, 60, 4 })));

	manager.Release();
}

