void TestNetworkStream() {
#if defined(BPP_HAS_POSIX_SOCKETS)
	int fds[2] = { -1, -1 };
	CHECK_EQ(::socketpair(AF_UNIX, SOCK_STREAM, 0, fds), 0);
	if (fds[0] < 0 || fds[1] < 0)
		return;
	const int flags = ::fcntl(fds[1], F_GETFL, 0);
	::fcntl(fds[1], F_SETFL, flags | O_NONBLOCK);

	NetworkStream writer(fds[0]);
	NetworkStream reader(fds[1]);
	writer.Write<uint16_t>(0x1234);
	writer.WriteString8("hello");
	writer.WriteString16("héllo ☃");
	writer.Write<uint32_t>(0xDEADBEEF);
	CHECK(writer.FlushWriteBuffer());
	reader.DrainToBuffer();

	CHECK_EQ(reader.Read<uint16_t>(), uint16_t(0x1234));
	CHECK_EQ(reader.ReadString8(), std::string("hello"));
	CHECK_EQ(reader.ReadString16(), std::string("héllo ☃"));
	CHECK_EQ(reader.Read<uint32_t>(), uint32_t(0xDEADBEEF));
	CHECK(!reader.IsShortRead());
	CHECK(!reader.HasData());

	// A short read must be recoverable via Mark()/Rollback().
	writer.Write<uint32_t>(0x01020304);
	writer.FlushWriteBuffer();
	reader.DrainToBuffer();
	const size_t mark = reader.Mark();
	CHECK_EQ(reader.Read<uint32_t>(), uint32_t(0x01020304));
	reader.Rollback(mark);
	CHECK_EQ(reader.Read<uint32_t>(), uint32_t(0x01020304));

	// String-16 bodies split across two ticks must also roll back cleanly.
	NetworkStream encoded(-1);
	encoded.WriteString16("abc");
	const auto serialized = encoded.GetRawWriteBuffer();
	CHECK(serialized.size() > 4);
	::send(fds[0], serialized.data(), 4, 0);
	reader.DrainToBuffer();
	const size_t stringMark = reader.Mark();
	CHECK(reader.ReadString16().empty());
	CHECK(reader.IsShortRead());
	reader.Rollback(stringMark);
	::send(fds[0], serialized.data() + 4, serialized.size() - 4, 0);
	reader.DrainToBuffer();
	CHECK_EQ(reader.ReadString16(), std::string("abc"));
	CHECK(!reader.IsShortRead());
#endif
}

